<?php
$canManage=ccManage($user?:null);$manage=$canManage&&($_GET['manage']??'')==='1';
try{$year=ccYear($_GET['year']??date('Y'));}catch(Throwable $ex){$year=(int)date('Y');$error=$ex->getMessage();}
$month=max(0,min(12,(int)($_GET['month']??0)));$category=is_string($_GET['category']??'')?($_GET['category']??''):'';if(!isset(ccCategories()[$category]))$category='';
$ready=ccReady();$allEvents=$ready?ccEvents($year,$manage):[];$events=array_values(array_filter($allEvents,fn($v)=>$category===''||$v['category']===$category));
$editing=null;if($manage&&!empty($_GET['edit']))$editing=one("SELECT * FROM college_calendar_events WHERE id=? AND status<>'deleted'",[(int)$_GET['edit']]);
$values=$editing??['id'=>0,'revision'=>0,'title'=>'','category'=>'meeting','start_date'=>$year.'-'.sprintf('%02d',$month?:1).'-01','end_date'=>$year.'-'.sprintf('%02d',$month?:1).'-01','start_time'=>'','end_time'=>'','location'=>'','description'=>'','source'=>'','status'=>'draft'];
if($error&&($_POST['action']??'')==='cc_save'&&$manage)$values=array_merge($values,array_intersect_key($_POST,$values));
function ccLink(array $args=[]):string{global $year,$month,$category,$manage;return '?'.http_build_query(array_merge(['page'=>'calendar','year'=>$year,'month'=>$month,'category'=>$category,'manage'=>$manage?1:0],$args));}
function ccInput(string $name,string $label,array $values,string $type='text',bool $required=false):void{echo '<label>'.e($label).'<input type="'.$type.'" name="'.$name.'" value="'.e($values[$name]??'').'" '.($required?'required':'').'></label>';}
function ccMonth(int $year,int $month,array $events,bool $large):void{
 $first=new DateTimeImmutable(sprintf('%04d-%02d-01',$year,$month));$days=(int)$first->format('t');$offset=(int)$first->format('N')-1;$last=$first->format('Y-m-').$days;$visible=array_values(array_filter($events,fn($e)=>$e['start_date']<=$last&&$e['end_date']>=$first->format('Y-m-d')));
 echo '<section class="cc-month '.($large?'cc-large':'').'"><div class="cc-month-title"><h2><a href="'.e(ccLink(['month'=>$month])).'">'.$first->format('F').'</a></h2><span>'.count($visible).' events</span></div><div class="cc-weekdays">';foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $d)echo '<span>'.$d.'</span>';echo '</div><div class="cc-days">';
 for($i=0;$i<$offset;$i++)echo '<div class="cc-empty"></div>';
 for($d=1;$d<=$days;$d++){$date=$first->format('Y-m-').sprintf('%02d',$d);$today=$date===date('Y-m-d');$items=array_values(array_filter($visible,fn($e)=>$e['start_date']<=$date&&$e['end_date']>=$date));$holiday=(bool)array_filter($items,fn($e)=>$e['category']==='holiday');$weekend=(int)(new DateTimeImmutable($date))->format('N')>=6;
 echo '<div class="cc-day'.($today?' cc-today':'').($weekend?' cc-weekend':'').($holiday?' cc-holiday':'').'"><a class="cc-day-number" href="'.e(ccLink(['month'=>$month])).'#agenda" aria-label="'.e($date.($today?', today':'')).'">'.$d.'</a><div class="cc-dots" aria-hidden="true">';foreach(array_unique(array_column($items,'category')) as $c)echo '<i class="cc-dot cc-'.$c.'"></i>';echo '</div>';
 if($large)foreach($items as $e)echo '<a class="cc-day-event cc-'.$e['category'].'" href="#event-'.$e['id'].'">'.e(($e['start_time']!==''?$e['start_time'].' ':'').$e['title']).'</a>';echo '</div>';
 }
 echo '</div>';if(!$large){echo '<div class="cc-month-preview">';foreach(array_slice($visible,0,2) as $e)echo '<p><span class="cc-dot cc-'.$e['category'].'"></span><b>'.e(ccRange($e)).'</b> '.e($e['title']).'</p>';if(count($visible)>2)echo '<a href="'.e(ccLink(['month'=>$month])).'">View all '.count($visible).' events →</a>';elseif(!$visible)echo '<p>No events published</p>';echo '</div>';}echo '</section>';
}
function ccYearSheet(int $year,array $events):void{
 echo '<div class="cc-sheet" aria-label="Annual college calendar"><div class="cc-sheet-heading"><div>Month / Calendar</div><div>Meetings</div><div>Assessment</div><div>Others</div></div>';
 for($month=1;$month<=12;$month++){
  $first=sprintf('%04d-%02d-01',$year,$month);$last=(new DateTimeImmutable($first))->format('Y-m-t');
  $items=array_values(array_filter($events,fn($e)=>$e['start_date']<=$last&&$e['end_date']>=$first));
  echo '<section class="cc-sheet-row" aria-label="'.date('F',strtotime($first)).'"><div class="cc-sheet-calendar">';ccMonth($year,$month,$events,false);
  foreach($items as $event)if(in_array($event['category'],['holiday','local'],true)){echo '<div class="cc-sheet-holiday cc-'.$event['category'].'"><strong>'.e(ccRange($event)).'</strong> '.e($event['title']).'<small>'.e(ccCategories()[$event['category']]).($event['status']==='draft'?' · DRAFT':'').'</small></div>';}
  echo '</div>';
  foreach(['meeting'=>'Meetings','assessment'=>'Assessment','other'=>'Others'] as $category=>$label){echo '<div class="cc-sheet-events"><h3 class="cc-sheet-mobile-label">'.$label.'</h3>';$found=false;foreach($items as $event){if($event['category']!==$category)continue;$found=true;echo '<article class="cc-sheet-entry cc-'.$category.'"><strong>'.e(ccRange($event)).'</strong><p>'.e($event['title']).'</p>';if($event['status']==='draft')echo '<small>DRAFT — editors only</small>';if($event['location'])echo '<small>'.e($event['location']).'</small>';if($event['description'])echo '<p class="cc-description">'.e($event['description']).'</p>';echo '</article>';}
  if(!$found)echo '<p class="cc-sheet-none">—</p>';echo '</div>';}
  echo '</section>';
 }
 echo '</div>';
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>College Calendar <?=$year?></title><link rel="stylesheet" href="assets/college-calendar.css?v=2"><script src="assets/college-calendar.js?v=1" defer></script></head><body><main class="cc-shell">
<div class="cc-top"><h1>College Calendar <span><?=$year?></span></h1><nav aria-label="Calendar actions"><?php if($canManage):?><a href="<?=e(ccLink(['manage'=>$manage?0:1,'edit'=>null]))?>"><?=$manage?'Public view':'Manage calendar'?></a><a href="./">Academic system</a><?php else:?><a href="?page=login">Official login</a><?php endif;?><button type="button" id="cc-print">Print calendar</button></nav></div>
<?php if($message):?><p class="cc-notice" role="status"><?=e($message)?></p><?php endif;if($error):?><p class="cc-notice cc-error" role="alert"><?=e($error)?></p><?php endif;if(!$ready):?><p class="cc-notice">The college calendar is being prepared.<?php if($canManage):?> Run the calendar migration to enable event management.<?php endif;?></p><?php endif;?>
<form method="get" class="cc-controls"><input type="hidden" name="page" value="calendar"><input type="hidden" name="manage" value="<?=$manage?1:0?>"><label>Year<input type="number" name="year" min="2000" max="2100" value="<?=$year?>" required></label><label>View<select name="month"><option value="0">Full year</option><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>" <?=$m===$month?'selected':''?>><?=date('F',mktime(0,0,0,$m,1,$year))?></option><?php endfor;?></select></label><label>Category<select name="category"><option value="">All events</option><?php foreach(ccCategories() as $key=>$label):?><option value="<?=$key?>" <?=$key===$category?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><button>View calendar</button><a href="<?=e(ccLink(['year'=>date('Y'),'month'=>date('n')]))?>">This month</a></form>
<div class="cc-legend"><?php foreach(ccCategories() as $key=>$label):?><span><i class="cc-dot cc-<?=$key?>"></i><?=e($label)?></span><?php endforeach;?></div>
<?php if($manage&&$ready):?>
<section class="cc-editor"><div><h2><?=$values['id']?'Edit event':'Add an event'?></h2><p>Published events are visible to everyone. Dates and times use Bhutan time. Leave times blank for an all-day event.</p></div><form method="post" action="<?=e(ccLink())?>">
<?php csrf();?><input type="hidden" name="action" value="cc_save"><input type="hidden" name="year" value="<?=$year?>"><input type="hidden" name="id" value="<?=(int)$values['id']?>"><input type="hidden" name="revision" value="<?=(int)$values['revision']?>">
<div class="cc-form-grid"><?php ccInput('title','Event title',$values,'text',true);?><label>Category<select name="category"><?php foreach(ccCategories() as $key=>$label):?><option value="<?=$key?>" <?=$values['category']===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><?php ccInput('start_date','Start date',$values,'date',true);ccInput('end_date','End date (inclusive)',$values,'date',true);ccInput('start_time','Start time (optional)',$values,'time');ccInput('end_time','End time (optional)',$values,'time');ccInput('location','Location (optional)',$values);?><label>Visibility<select name="status"><option value="draft" <?=$values['status']==='draft'?'selected':''?>>Draft — editors only</option><option value="published" <?=$values['status']==='published'?'selected':''?>>Published — visible to staff</option></select></label><label class="cc-wide">Details<textarea name="description" rows="3" maxlength="4000"><?=e($values['description'])?></textarea></label><label class="cc-wide">Source / holiday notice (optional)<input name="source" maxlength="500" value="<?=e($values['source'])?>"></label></div><div class="cc-actions"><button>Save event</button><?php if($values['id']):?><a href="<?=e(ccLink(['edit'=>null]))?>">Cancel editing</a><?php endif;?></div></form></section>
<details class="cc-editor"><summary>National holidays for <?=$year?></summary><p>The 2026 holidays come from your college workbook. For later years, add fixed-date suggestions below, check the official notice and publish them. Enter lunar holidays and any special/local holidays using their announced dates. Suggestions are drafts and never automatically become public.</p><p><a href="https://www.moha.gov.bt/" target="_blank" rel="noopener noreferrer">Ministry of Home Affairs</a> · This calendar does not automatically change attendance or examination deadlines.</p><form method="post"><?php csrf();?><input type="hidden" name="action" value="cc_holidays"><input type="hidden" name="year" value="<?=$year?>"><button>Add fixed-date holiday drafts</button></form></details>
<?php endif;?>
<div class="cc-navigation"><a href="<?=e(ccLink(['year'=>max(2000,$year-1)]))?>">← <?=$year-1?></a><?php if($month):?><a href="<?=e(ccLink(['month'=>0]))?>">All 12 months</a><?php else:?><span>January – December</span><?php endif;?><a href="<?=e(ccLink(['year'=>min(2100,$year+1)]))?>"><?=$year+1?> →</a></div>
<div class="<?=$month?'cc-month-view':'cc-sheet-view'?>"><?php if($month)ccMonth($year,$month,$events,true);else ccYearSheet($year,$events);?></div>
<?php $agenda=array_values(array_filter($events,fn($e)=>!$month||($e['start_date']<=date('Y-m-t',mktime(0,0,0,$month,1,$year))&&$e['end_date']>=sprintf('%04d-%02d-01',$year,$month))));?>
<?php if($month||$manage):?><section id="agenda" class="cc-agenda"><h2><?=$month?date('F',mktime(0,0,0,$month,1,$year)):'Year'?> events <span><?=count($agenda)?></span></h2><?php if(!$agenda):?><p>No <?=$manage?'':'published '?>events for this selection.</p><?php endif;foreach($agenda as $e):?><article id="event-<?=(int)$e['id']?>" class="cc-event cc-<?=e($e['category'])?>"><div class="cc-event-date"><?=e(ccRange($e))?><small><?=substr($e['start_date'],0,4)?><?=$e['start_time']===''?' · All day':' · Bhutan time'?></small></div><div class="cc-event-body"><span class="cc-category"><?=e(ccCategories()[$e['category']])?><?=$e['status']==='draft'?' · DRAFT':''?></span><h3><?=e($e['title'])?></h3><?php if($e['location']):?><p><?=e($e['location'])?></p><?php endif;if($e['description']):?><p class="cc-description"><?=e($e['description'])?></p><?php endif;if($manage&&$e['source']):?><small>Source: <?=e($e['source'])?></small><?php endif;?></div><?php if($manage):?><div class="cc-event-actions"><a href="<?=e(ccLink(['edit'=>$e['id']]))?>">Edit</a><form method="post" class="cc-delete"><?php csrf();?><input type="hidden" name="action" value="cc_delete"><input type="hidden" name="year" value="<?=$year?>"><input type="hidden" name="id" value="<?=(int)$e['id']?>"><input type="hidden" name="revision" value="<?=(int)$e['revision']?>"><button class="cc-danger">Delete</button></form></div><?php endif;?></article><?php endforeach;?></section><?php endif;?>
<footer>College calendar · All times are Bhutan time<?php if($manage):?> · Changes are recorded in the calendar audit history.<?php endif;?></footer>
<?php if($manage&&$editing):?><details class="cc-editor"><summary>Event change history</summary><?php foreach(all('SELECT a.*,u.name FROM college_calendar_audit a LEFT JOIN users u ON u.id=a.actor_id WHERE event_id=? ORDER BY a.id DESC',[$editing['id']]) as $log):?><p><?=e($log['created_at'].' · '.$log['action'].' · '.($log['name']??'System'))?></p><?php endforeach;?></details><?php endif;?>
</main></body></html>
